create temporary table preserved on commit drop as select
 (select jsonb_agg(to_jsonb(d) order by id) from public.distributors d) as distributors,
 (select jsonb_agg(to_jsonb(p) order by id) from public.products p) as products;
delete from public.payments where id in (11,12);
delete from public.orders where id in ('302f1e34-223e-41a9-b002-bb3001d55b24'::uuid,'8729ecc7-4238-4d08-b9f1-acd3fb311019'::uuid,'b9184dae-974c-474e-9f37-bf4b2717e824'::uuid,'e97f6367-a314-4aba-b88a-ec782e41437e'::uuid,'ec6db857-02f2-4948-adaf-8d4180e8123d'::uuid);
do $$ begin
if exists(select 1 from public.orders) or exists(select 1 from public.payments) or exists(select 1 from public.order_items) or exists(select 1 from public.order_history) then raise exception 'Cleanup verification failed'; end if;
if exists(select 1 from preserved b where b.distributors is distinct from (select jsonb_agg(to_jsonb(d) order by id) from public.distributors d) or b.products is distinct from (select jsonb_agg(to_jsonb(p) order by id) from public.products p)) then raise exception 'Unrelated data changed'; end if;
end $$;
select (select count(*) from public.orders) as orders_remaining,
 (select count(*) from public.payments) as payments_remaining,
 (select count(*) from public.order_items) as items_remaining,
 (select count(*) from public.order_history) as history_remaining,
 (select sum(debt) from public.distributor_stats) as remaining_debt;
